(function(){'use strict';
const toast=document.getElementById('ai-toast'),mediaPreview=document.getElementById('media-preview'),peoplePreview=document.getElementById('people-preview');let timer;
function notify(message){toast.textContent=message;toast.hidden=false;clearTimeout(timer);timer=setTimeout(()=>toast.hidden=true,2400)}
function view(name){document.querySelectorAll('[data-view]').forEach(el=>el.hidden=el.dataset.view!==name);mediaPreview.hidden=name!=='search';peoplePreview.hidden=name!=='people';history.replaceState(null,'','#'+name);document.querySelector('[data-view="'+name+'"] h1').focus({preventScroll:true})}
document.querySelectorAll('[data-view-target]').forEach(button=>button.addEventListener('click',()=>view(button.dataset.viewTarget)));
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-mode]').forEach(item=>item.classList.toggle('active',item===button));document.getElementById('global-query').placeholder=button.dataset.mode==='semantic'?'描述想找的画面':'搜索文件名或路径';notify(button.dataset.mode==='semantic'?'已切换到画面语义搜索':'已切换到文件名搜索')}));
document.querySelectorAll('.choice-group').forEach(group=>group.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;group.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button))}));
document.getElementById('global-search-form').addEventListener('submit',event=>{event.preventDefault();view('search');const query=document.getElementById('global-query').value.trim();document.getElementById('results-title').textContent=query?'“'+query+'”的相似结果':'与描述最接近';notify('已查询本地智能索引')});
document.querySelectorAll('.media-card').forEach(card=>card.addEventListener('click',()=>{document.querySelectorAll('.media-card').forEach(item=>item.classList.toggle('selected',item===card));const src='assets/ai-media/'+card.dataset.image;document.getElementById('preview-image').src=src;document.getElementById('face-image').src=src;document.getElementById('preview-name').textContent=card.dataset.name;document.getElementById('preview-score').textContent=card.dataset.score+'% · 画面匹配';mediaPreview.hidden=false}));
document.getElementById('close-preview').addEventListener('click',()=>mediaPreview.hidden=true);
document.getElementById('assign-face').addEventListener('click',()=>{view('people');notify('已打开建议的人脸组，请由你确认归属')});
document.querySelectorAll('[data-tag]').forEach(button=>button.addEventListener('click',()=>{const accepted=button.classList.toggle('accepted');const label=button.textContent.trim();button.innerHTML=label+' <i class="ph ph-'+(accepted?'check':'plus')+'"></i>';notify(accepted?'建议已转为人工标签':'已撤销这次确认')}));
document.querySelectorAll('.cluster-card').forEach(card=>card.addEventListener('click',()=>{document.querySelectorAll('.cluster-card').forEach(item=>item.classList.toggle('selected',item===card));card.dataset.images.split(',').forEach((name,index)=>document.querySelectorAll('#cluster-detail-images img')[index].src='assets/ai-media/'+name);document.getElementById('cluster-detail-title').textContent='未命名组 '+card.dataset.cluster;document.getElementById('cluster-detail-copy').textContent=card.dataset.count+' 张图片。系统只判断相似，不知道她是谁。';peoplePreview.hidden=false}));
document.querySelectorAll('[data-person-mode]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-person-mode]').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('[data-person-panel]').forEach(panel=>panel.hidden=panel.dataset.personPanel!==button.dataset.personMode)}));
document.getElementById('confirm-person').addEventListener('click',()=>{if(!document.getElementById('person-name').value.trim()){document.getElementById('person-name').focus();notify('请先输入由你决定的人物名称');return}notify('人物已建立；系统不会用名称反推身份')});
document.getElementById('confirm-merge').addEventListener('click',()=>notify('该匿名组已人工并入已有的人物'));
document.getElementById('exclude-edge').addEventListener('click',()=>notify('边缘人脸已排除，不影响原媒体'));
document.getElementById('close-people-preview').addEventListener('click',()=>peoplePreview.hidden=true);
view(location.hash==='#people'?'people':'search');
}());
